function parseThresholds(thresholdStrings?: string[], evaluations?: any[]): { thresholds: Record<string, number> | undefined; validMetricIds?: string[] } {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds: undefined };
  }

  const thresholds: Record<string, number> = {};
  const validMetricIds = evaluations ? evaluations.map((m: any) => m.id) : [];

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
    if (!match) {
      return {
        thresholds: undefined,
        validMetricIds
      };
    }

    const [, metricId, minStr] = match;
    const min = parseFloat(minStr);

    if (!Number.isFinite(min) || min < 0 || min > 1) {
      return {
        thresholds: undefined,
        validMetricIds
      };
    }

    if (!validMetricIds.includes(metricId)) {
      return {
        thresholds: undefined,
        validMetricIds
      };
    }

    thresholds[metricId] = min;
  }

  return { thresholds };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let thresholds: Record<string, number> | undefined;
  if (options.threshold && options.threshold.length > 0) {
    const parsed = parseThresholds(options.threshold, evaluations);
    if (!parsed.thresholds && parsed.validMetricIds) {
      const invalidThreshold = options.threshold.find((t) => {
        const match = t.match(/^([a-z_]+)=(.+)$/);
        if (!match) return true;
        const [, metricId, minStr] = match;
        const min = parseFloat(minStr);
        if (!Number.isFinite(min) || min < 0 || min > 1) return true;
        if (!parsed.validMetricIds!.includes(metricId)) return true;
        return false;
      });

      if (invalidThreshold) {
        const match = invalidThreshold.match(/^([a-z_]+)=(.+)$/);
        if (!match) {
          log.error(`Invalid threshold format: ${invalidThreshold}. Expected format: <metric>=<min>`);
        } else {
          const [, metricId, minStr] = match;
          const min = parseFloat(minStr);
          if (!Number.isFinite(min) || min < 0 || min > 1) {
            log.error(`Invalid threshold value: ${minStr}. Must be a number between 0 and 1.`);
          } else {
            log.error(`Unknown metric: ${metricId}. Valid metrics: ${parsed.validMetricIds!.join(', ')}`);
          }
        }
      }
      process.exit(2);
    }
    thresholds = parsed.thresholds;
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    process.exit(1);
  }
}

