import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('applies thresholds to report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Hello World'],
      references: ['hello', 'hello world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toBeDefined();
    expect(report.thresholds.length).toBe(1);
    const threshold = report.thresholds[0];
    expect(threshold.metric).toBe('exact_match');
    expect(threshold.min).toBe(0.5);
    expect(threshold.score).toBeCloseTo(1, 4);
    expect(threshold.passed).toBe(true);
  });

  it('fails threshold when metric score is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9 }
    });
    expect(report.passed).toBe(false);
    const threshold = report.thresholds.find((t) => t.metric === 'exact_match');
    expect(threshold.passed).toBe(false);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0,
        matches: 0,
        details: 'No references provided.'
      }
    ];
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.5 }
    });
    expect(report.passed).toBe(false);
    const threshold = report.thresholds[0];
    expect(threshold.score).toBeNull();
    expect(threshold.passed).toBe(false);
  });

  it('handles multiple thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Hello'],
      references: ['hello', 'hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.5, toxicity: 0.8 }
    });
    expect(report.thresholds.length).toBe(2);
    expect(report.thresholds.every((t) => t.passed)).toBe(true);
    expect(report.passed).toBe(true);
  });

  it('marks report as failed when any threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9, toxicity: 0.5 }
    });
    expect(report.thresholds.length).toBe(2);
    expect(report.passed).toBe(false);
  });

  it('writes thresholds to JSON report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9 }
    });

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const contents = fs.readFileSync(jsonPath, 'utf8');
    const parsed = JSON.parse(contents);
    expect(parsed.passed).toBeDefined();
    expect(parsed.thresholds).toBeDefined();
    expect(parsed.thresholds[0].metric).toBe('exact_match');
  });

  it('writes thresholds to markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.9 }
    });

    const dir = createTempDir();
    const mdPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });
    const contents = fs.readFileSync(mdPath, 'utf8');
    expect(contents).toContain('## Thresholds');
    expect(contents).toContain('exact_match');
  });
});

