export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const thresholdList = [];
    let allPassed = true;

    Object.entries(thresholds).forEach(([metricId, min]) => {
      const metric = evaluations.find((m) => m.id === metricId);
      const passed = metric && typeof metric.score === 'number' && metric.score >= min;
      if (!passed) allPassed = false;

      thresholdList.push({
        metric: metricId,
        min,
        score: metric ? metric.score : null,
        passed: Boolean(passed)
      });
    });

    report.passed = allPassed;
    report.thresholds = thresholdList;
  }

  return report;
}

